// src/pages/Profile.js

import { FiSettings } from "react-icons/fi";
import { useNavigate } from "react-router-dom";

const books = [
  {
    title: "노르웨이의 숲",
    review:
      "상실 이후에도 사람은 계속 살아간다는 점이 가장 인상 깊었다.",
  },

  {
    title: "데미안",
    review:
      "자기 자신을 찾아가는 과정이 정말 인상 깊었다.",
  },

  {
    title: "어린왕자",
    review:
      "어른이 된다는 건 무엇일까 다시 생각하게 만든 책이었다.",
  },

  {
    title: "1984",
    review:
      "감시 사회의 무서움을 현실적으로 보여줘서 몰입감이 강했다.",
  },

  {
    title: "해변의 카프카",
    review:
      "현실과 환상이 섞이는 분위기가 매력적이었다.",
  },

  {
    title: "채식주의자",
    review:
      "인물의 심리 변화가 굉장히 강렬했다.",
  },
];

function Profile() {
  const navigate = useNavigate();

  const currentUser = JSON.parse(
    localStorage.getItem("currentUser")
  );

  const userName =
    currentUser?.name || "READLY";

  const totalHeight =
    books.length * 2;

  const SHELF_SIZE = 5;

  const shelves = [];

  for (
    let i = 0;
    i < books.length;
    i += SHELF_SIZE
  ) {
    shelves.push(
      books.slice(i, i + SHELF_SIZE)
    );
  }

  const reversedShelves =
    [...shelves].reverse();

  return (
    <div className="page">
      {/* 상단 */}

      <div className="profile-header">
        <div className="logo">
          READLY
        </div>

        <FiSettings className="setting-icon" />
      </div>

      {/* 프로필 */}

      <div className="profile-top">
        <div className="profile-image"></div>

        <div className="profile-info">
          <div className="profile-name">
            {userName} ✏️
          </div>

          <div className="follow-wrap">
            <div className="follow-box">
              <div className="follow-num">
                100
              </div>

              <div className="follow-text">
                팔로워
              </div>
            </div>

            <div className="follow-box">
              <div className="follow-num">
                100
              </div>

              <div className="follow-text">
                팔로잉
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* 소개 */}

      <div className="profile-desc">
        에세이를 좋아하는 책린이 입니다!
        <br />
        instagram: xx_123
      </div>

      <div className="line"></div>

      {/* 책장 */}

      <div className="books-section">
        <div className="stack-message">
          현재 {totalHeight}cm만큼
          쌓였어요!
          <br />
          조금 더 분발해요!
        </div>

        <div className="book-stack-wrap">
          {reversedShelves.map(
            (shelf, shelfIndex) => (
              <div
                className="shelf-floor"
                key={shelfIndex}
              >
                {shelf.map(
                  (book, index) => (
                    <div
                      key={index}
                      className="book-item"
                      onClick={() =>
                        navigate(
                          "/review",
                          {
                            state: {
                              title:
                                book.title,
                              review:
                                book.review,
                            },
                          }
                        )
                      }
                    >
                      {book.title}
                    </div>
                  )
                )}

                <div className="shelf-line"></div>
              </div>
            )
          )}
        </div>
      </div>
    </div>
  );
}

export default Profile;
